ALTER TABLE groups ADD COLUMN group_type TEXT NOT NULL DEFAULT 'Friends';
ALTER TABLE groups ADD COLUMN timezone TEXT NOT NULL DEFAULT 'UTC';
ALTER TABLE groups ADD COLUMN country TEXT NOT NULL DEFAULT 'TR';
ALTER TABLE groups ADD COLUMN leagues JSONB NOT NULL DEFAULT '[203]';
ALTER TABLE groups ADD COLUMN pending_settings JSONB;
ALTER TABLE rounds ADD COLUMN group_type TEXT NOT NULL DEFAULT 'Friends';
ALTER TABLE rounds ADD COLUMN timezone TEXT NOT NULL DEFAULT 'UTC';
ALTER TABLE rounds ADD COLUMN leagues JSONB NOT NULL DEFAULT '[]';
ALTER TABLE rounds ADD COLUMN pick_end_at TIMESTAMPTZ;
UPDATE rounds SET pick_end_at=deadline_at;
ALTER TABLE rounds ADD COLUMN fixture_end_at TIMESTAMPTZ;
ALTER TABLE rounds ADD COLUMN content_ready BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE rounds ADD COLUMN skip_reason TEXT;
CREATE TABLE football_leagues (id INTEGER PRIMARY KEY,name TEXT NOT NULL,country TEXT NOT NULL,season INTEGER NOT NULL,checked_at TIMESTAMPTZ NOT NULL);
CREATE TABLE football_fixtures (id TEXT PRIMARY KEY,provider TEXT NOT NULL,provider_id INTEGER NOT NULL,league_id INTEGER NOT NULL,league_name TEXT NOT NULL,home TEXT NOT NULL,away TEXT NOT NULL,kickoff TIMESTAMPTZ NOT NULL,status TEXT NOT NULL,home90 INTEGER,away90 INTEGER,home_rank INTEGER,away_rank INTEGER,revision TEXT NOT NULL,observed_at TIMESTAMPTZ NOT NULL,needs_review BOOLEAN NOT NULL DEFAULT false,UNIQUE(provider,provider_id));
CREATE TABLE football_fixture_revisions (id TEXT PRIMARY KEY,fixture_id TEXT REFERENCES football_fixtures(id),revision TEXT NOT NULL,payload JSONB NOT NULL,observed_at TIMESTAMPTZ NOT NULL,UNIQUE(fixture_id,revision));
CREATE TABLE football_feed_windows (league_id INTEGER NOT NULL,from_at TIMESTAMPTZ NOT NULL,to_at TIMESTAMPTZ NOT NULL,fetched_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(league_id,from_at,to_at));
CREATE TABLE football_feed_status (id TEXT PRIMARY KEY,last_attempt TIMESTAMPTZ,last_success TIMESTAMPTZ,next_poll TIMESTAMPTZ,error TEXT);
CREATE TABLE football_skipped_weeks (group_id TEXT REFERENCES groups(id),opens_at TIMESTAMPTZ NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(group_id,opens_at));
ALTER TABLE questions ADD COLUMN market TEXT NOT NULL DEFAULT 'custom';
ALTER TABLE questions ADD COLUMN fixture_id TEXT REFERENCES football_fixtures(id);
ALTER TABLE questions ADD COLUMN slot TEXT NOT NULL DEFAULT 'custom';
ALTER TABLE questions ADD COLUMN superseded BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE questions ADD COLUMN selection_reason TEXT;
ALTER TABLE questions ADD COLUMN void_reason TEXT;
ALTER TABLE questions ADD COLUMN result_revision TEXT;
ALTER TABLE predictions DROP CONSTRAINT predictions_answer_check;
ALTER TABLE predictions ADD COLUMN submitted_at TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE UNIQUE INDEX football_market_unique ON questions(round_id,fixture_id,market) WHERE fixture_id IS NOT NULL AND NOT superseded;
CREATE TABLE football_score_revisions (id TEXT PRIMARY KEY,question_id TEXT REFERENCES questions(id),user_id TEXT REFERENCES users(id),revision TEXT NOT NULL,old_points NUMERIC(28,12),new_points NUMERIC(28,12) NOT NULL,changed_at TIMESTAMPTZ NOT NULL,UNIQUE(question_id,user_id,revision));
CREATE TABLE football_review_flags (question_id TEXT REFERENCES questions(id),revision TEXT NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(question_id,revision));
